#include "register/op_def_registry.h"
#include "conv_standard_2d_square_input_asymmetric_kernel_dilated_padded_custom_tiling.h"

namespace {
inline int64_t floor_div(int64_t a, int64_t b) { return a / b; }
}

namespace optiling {
static const uint32_t BLOCK_DIM = 8;

// 读取属性的工具函数（若未设置则使用默认值）
static inline int64_t GetIntAttrSafe(gert::TilingContext* context, const char* name, int64_t defVal) {
    int64_t v = defVal;
    auto attrs = context->GetAttrs();
    if (attrs != nullptr) {
        (void)attrs->GetInt(name, v);
    }
    return v;
}

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvStandard2dSquareInputAsymmetricKernelDilatedPaddedCustomTilingData tiling;

    // x: NCHW, w: Cout x Cin x Kh x Kw
    const gert::Shape* xShape = context->GetInputShape(0);
    const gert::Shape* wShape = context->GetInputShape(1);

    int64_t n = xShape->GetDim(0);
    int64_t cin = xShape->GetDim(1);
    int64_t h = xShape->GetDim(2);
    int64_t w = xShape->GetDim(3);

    int64_t cout = wShape->GetDim(0);
    int64_t cin_w = wShape->GetDim(1);
    int64_t kh = wShape->GetDim(2);
    int64_t kw = wShape->GetDim(3);

    // 获取stride/pad/dilation（默认与PyTorch Conv2d一致：stride=1，pad=0，dilation=1）
    int64_t stride_h = GetIntAttrSafe(context, "stride_h", 1);
    int64_t stride_w = GetIntAttrSafe(context, "stride_w", 1);
    int64_t pad_top = GetIntAttrSafe(context, "pad_top", 0);
    int64_t pad_bottom = GetIntAttrSafe(context, "pad_bottom", 0);
    int64_t pad_left = GetIntAttrSafe(context, "pad_left", 0);
    int64_t pad_right = GetIntAttrSafe(context, "pad_right", 0);
    int64_t dilation_h = GetIntAttrSafe(context, "dilation_h", 1);
    int64_t dilation_w = GetIntAttrSafe(context, "dilation_w", 1);

    if (cin != cin_w) {
        return ge::GRAPH_FAILED;
    }

    // 参考文档公式：
    // Ho = floor((H + pad_top + pad_bottom - dilation_h * (Kh - 1) - 1) / stride_h + 1)
    // Wo = floor((W + pad_left + pad_right - dilation_w * (Kw - 1) - 1) / stride_w + 1)
    int64_t ho = floor_div((h + pad_top + pad_bottom - dilation_h * (kh - 1) - 1), stride_h) + 1;
    int64_t wo = floor_div((w + pad_left + pad_right - dilation_w * (kw - 1) - 1), stride_w) + 1;

    if (ho <= 0 || wo <= 0) {
        return ge::GRAPH_FAILED;
    }

    tiling.set_n(static_cast<uint32_t>(n));
    tiling.set_cin(static_cast<uint32_t>(cin));
    tiling.set_cout(static_cast<uint32_t>(cout));
    tiling.set_h(static_cast<uint32_t>(h));
    tiling.set_w(static_cast<uint32_t>(w));
    tiling.set_kh(static_cast<uint32_t>(kh));
    tiling.set_kw(static_cast<uint32_t>(kw));

    tiling.set_stride_h(static_cast<uint32_t>(stride_h));
    tiling.set_stride_w(static_cast<uint32_t>(stride_w));
    tiling.set_pad_top(static_cast<uint32_t>(pad_top));
    tiling.set_pad_bottom(static_cast<uint32_t>(pad_bottom));
    tiling.set_pad_left(static_cast<uint32_t>(pad_left));
    tiling.set_pad_right(static_cast<uint32_t>(pad_right));
    tiling.set_dilation_h(static_cast<uint32_t>(dilation_h));
    tiling.set_dilation_w(static_cast<uint32_t>(dilation_w));

    tiling.set_ho(static_cast<uint32_t>(ho));
    tiling.set_wo(static_cast<uint32_t>(wo));

    uint64_t totalOut = static_cast<uint64_t>(n) * static_cast<uint64_t>(cout) * static_cast<uint64_t>(ho) * static_cast<uint64_t>(wo);
    tiling.set_totalOut(totalOut);

    context->SetBlockDim(BLOCK_DIM);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

