import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    使用自定义AscendC算子替换标准Conv2d（方形输入+非对称卷积核+膨胀+dilation与padding）。
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1,
                 padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        assert bias is False, "当前自定义算子示例未实现bias，请设为False。"
        kh, kw = kernel_size
        self.weight = torch.nn.Parameter(torch.empty(out_channels, in_channels, kh, kw))
        # 使用Kaiming初始化
        torch.nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        # 保存卷积超参
        self.stride_h = int(stride) if isinstance(stride, int) else int(stride[0])
        self.stride_w = int(stride) if isinstance(stride, int) else int(stride[1])
        self.pad_top = int(padding[0])
        self.pad_bottom = int(padding[0])
        self.pad_left = int(padding[1])
        self.pad_right = int(padding[1])
        self.dilation_h = int(dilation[0])
        self.dilation_w = int(dilation[1])

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return custom_ops_lib.conv_standard_2d_square_input_asymmetric_kernel_dilated_padded_custom(
            x, self.weight,
            self.stride_h, self.stride_w,
            self.pad_top, self.pad_bottom, self.pad_left, self.pad_right,
            self.dilation_h, self.dilation_w
        )
